#!/usr/bin/env bash
#
# Builds the engine data files (uzdoom.pk3 and friends) with the *host*
# toolchain and copies them into android/app/src/main/assets.
#
# The PK3s are produced by zipdir, which only runs on the build machine, so they
# cannot be generated by the NDK build. This script does a second, host-native
# CMake configure of this same source tree that only builds those targets.
#
# SPDX-License-Identifier: GPL-3.0-or-later
#
# Usage:  ./android/scripts/build-host-assets.sh [--clean]

set -euo pipefail

ANDROID_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_ROOT="$(cd "$ANDROID_DIR/.." && pwd)"
BUILD_DIR="$REPO_ROOT/build-host-assets"
ASSETS_DIR="$ANDROID_DIR/app/src/main/assets"

if [ "${1:-}" = "--clean" ]; then
    rm -rf "$BUILD_DIR"
fi

mkdir -p "$ASSETS_DIR"

echo "== Configuring host asset build in $BUILD_DIR"
cmake -S "$REPO_ROOT" -B "$BUILD_DIR" \
    -DCMAKE_BUILD_TYPE=Release \
    -DUZDOOM_HOST_ASSETS_ONLY=ON

# Build everything this configuration has: the PK3 targets *and* the host tools
# (re2c, lemon, zipdir). The PK3s only depend on zipdir, but the Android build
# needs re2c and lemon to generate two engine sources, so they must exist too.
echo "== Building host tools and engine data"
cmake --build "$BUILD_DIR" --parallel "$(nproc 2>/dev/null || echo 4)"

for tool in re2c lemon zipdir; do
    if [ ! -x "$BUILD_DIR/tools/$tool/$tool" ]; then
        echo "error: host tool $tool was not built in $BUILD_DIR/tools/$tool" >&2
        exit 1
    fi
done

# re2c/lemon/zipdir are exported here so the NDK build can run them.
if [ ! -f "$BUILD_DIR/ImportExecutables.cmake" ]; then
    echo "error: $BUILD_DIR/ImportExecutables.cmake was not generated" >&2
    exit 1
fi

# CMake exports the locations per configuration (IMPORTED_LOCATION_RELEASE),
# but the APK can be built as Debug or RelWithDebInfo, which would then find no
# location at all. One generic location is what we want: they are host tools,
# their configuration is irrelevant.
sed -i 's/IMPORTED_LOCATION_RELEASE/IMPORTED_LOCATION/g' "$BUILD_DIR/ImportExecutables.cmake"

echo "== Host tools exported to $BUILD_DIR/ImportExecutables.cmake"

echo "== Copying PK3s into the APK assets"
shopt -s nullglob
copied=0
for pk3 in "$BUILD_DIR"/*.pk3; do
    cp -v "$pk3" "$ASSETS_DIR/"
    copied=$((copied + 1))
done

if [ "$copied" -eq 0 ]; then
    echo "error: no PK3 files were produced" >&2
    exit 1
fi

echo "== Copying soundfont and FM banks"
rm -rf "$ASSETS_DIR/soundfonts" "$ASSETS_DIR/fm_banks"
mkdir -p "$ASSETS_DIR/soundfonts"
cp -v "$REPO_ROOT"/soundfont/* "$ASSETS_DIR/soundfonts/" 2>/dev/null || true
cp -rv "$REPO_ROOT/fm_banks" "$ASSETS_DIR/fm_banks"

echo "== Done. Assets are in $ASSETS_DIR"
ls -la "$ASSETS_DIR"
